$symbol = match ($store['currency']) { 'USD' => 'US$', 'EUR' => '€', default => 'RD$' };
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta name="theme-color" content="<?= e($store['primary_color']) ?>"><title>Carrito | <?= e($store['store_name']) ?></title><style>
:root{--brand:<?= e($store['primary_color']) ?>;--bg:<?= e($store['background_color']) ?>;--soft:<?= e($store['surface_color']) ?>;--ink:<?= e($store['text_color']) ?>;--muted:<?= e($store['muted_color']) ?>;--line:color-mix(in srgb,var(--ink) 12%,transparent);--radius:<?= (int)$store['border_radius'] ?>px;--shadow:0 20px 55px color-mix(in srgb,var(--ink) 9%,transparent)}*{box-sizing:border-box}body{margin:0;background:var(--soft);color:var(--ink);font:15px/1.55 Inter,system-ui,sans-serif}a{color:inherit;text-decoration:none}button{font:inherit}.container{width:min(1120px,calc(100% - 32px));margin:auto}.announcement{background:var(--brand);color:white;text-align:center;padding:8px 16px;font-size:13px;font-weight:800}.header{background:<?= e($store['header_color']) ?>;border-bottom:1px solid var(--line)}.header-inner{height:76px;display:flex;align-items:center;gap:20px}.brand{display:flex;align-items:center;gap:11px;font-size:20px;font-weight:950}.mark{width:44px;height:44px;border-radius:calc(var(--radius)*.7);background:var(--brand);color:white;display:grid;place-items:center;overflow:hidden}.mark img{width:100%;height:100%;object-fit:cover}.nav{margin-left:auto;display:flex;gap:9px}.nav a{height:42px;display:inline-flex;align-items:center;border:1px solid var(--line);border-radius:12px;padding:0 15px;font-weight:850}.nav .active{background:var(--brand);border-color:var(--brand);color:white}.page{padding:44px 0 80px}.breadcrumb{font-size:13px;color:var(--muted);margin-bottom:17px}.title{display:flex;justify-content:space-between;align-items:end;gap:20px;margin-bottom:26px}.title h1{font-size:clamp(31px,4vw,46px);line-height:1;margin:0}.title p{color:var(--muted);margin:9px 0 0}.clear{border:0;background:transparent;color:#be123c;font-weight:900;cursor:pointer}.layout{display:grid;grid-template-columns:minmax(0,1fr) 350px;gap:24px;align-items:start}.items,.summary{background:var(--bg);border:1px solid var(--line);border-radius:var(--radius);box-shadow:var(--shadow)}.items{overflow:hidden}.item{display:grid;grid-template-columns:100px 1fr auto;gap:17px;align-items:center;padding:19px;border-bottom:1px solid var(--line)}.item:last-child{border:0}.image{width:100px;height:90px;border-radius:calc(var(--radius)*.7);background:var(--soft);display:grid;place-items:center;overflow:hidden;color:var(--muted);font-size:30px}.image img{width:100%;height:100%;object-fit:cover}.info small{color:var(--brand);font-weight:900}.info h2{font-size:17px;line-height:1.25;margin:4px 0}.price{font-weight:950}.actions{display:flex;align-items:center;gap:10px}.qty{display:flex;border:1px solid var(--line);border-radius:10px;overflow:hidden}.qty button{width:34px;height:36px;border:0;background:var(--soft);cursor:pointer}.qty span{width:36px;display:grid;place-items:center;font-weight:900}.remove{width:36px;height:36px;border:0;border-radius:10px;background:#fff1f2;color:#be123c;cursor:pointer}.summary{position:sticky;top:20px;padding:24px}.summary h2{margin:0 0 20px}.shipping-progress{border-radius:13px;background:var(--soft);padding:12px;margin:-5px 0 18px;color:var(--muted);font-size:11px}.shipping-progress b{display:block;color:var(--ink);margin-bottom:7px}.shipping-bar{height:7px;border-radius:99px;background:color-mix(in srgb,var(--ink) 10%,transparent);overflow:hidden}.shipping-bar span{display:block;height:100%;width:0;border-radius:inherit;background:var(--brand);transition:width .25s}.line{display:flex;justify-content:space-between;gap:15px;margin:12px 0;color:var(--muted)}.line strong{color:var(--ink)}.total{display:flex;justify-content:space-between;border-top:1px solid var(--line);padding-top:17px;margin-top:17px;font-size:21px;font-weight:950}.checkout{width:100%;height:52px;border:0;border-radius:calc(var(--radius)*.7);margin-top:20px;background:var(--brand);color:white;font-weight:950;cursor:pointer}.checkout:disabled{opacity:.5;cursor:not-allowed}.continue{display:block;text-align:center;margin-top:14px;color:var(--brand);font-weight:850}.notice{display:flex;gap:8px;border-top:1px solid var(--line);padding-top:16px;margin-top:18px;color:var(--muted);font-size:12px}.empty{text-align:center;padding:65px 22px}.empty i{font-style:normal;font-size:35px}.empty h2{margin:8px 0}.empty p{color:var(--muted)}.button{display:inline-flex;min-height:47px;align-items:center;padding:0 20px;border-radius:12px;background:var(--brand);color:white;font-weight:900}.footer{background:<?= e($store['footer_color']) ?>;color:#cbd5e1;padding:32px 0}.footer .container{display:flex;justify-content:space-between;gap:20px}.footer strong{color:white}@media(max-width:850px){.layout{grid-template-columns:1fr}.summary{position:static}.item{grid-template-columns:88px 1fr}.image{width:88px;height:82px}.actions{grid-column:2}}@media(max-width:560px){.container{width:min(100% - 22px,1120px)}.nav a:first-child{display:none}.brand span:last-child{display:none}.page{padding:30px 0 55px}.title{align-items:start;flex-direction:column}.item{grid-template-columns:70px 1fr;padding:14px;gap:11px}.image{width:70px;height:70px}.actions{grid-column:1/-1}.footer .container{display:block}}
</style></head><body>
<?php if($store['announcement_enabled'] && $store['announcement_text']): ?><div class="announcement"><?= e($store['announcement_text']) ?></div><?php endif; ?>
<header class="header"><div class="container header-inner"><a class="brand" href="/store/<?= e($store['slug']) ?>"><span class="mark"><?php if($store['logo_url']): ?><img src="<?= e($store['logo_url']) ?>" alt=""><?php else: ?><?= e(mb_strtoupper(mb_substr($store['store_name'],0,1))) ?><?php endif; ?></span><span><?= e($store['store_name']) ?></span></a><nav class="nav"><a href="/store/<?= e($store['slug']) ?>/invoices">Mis facturas</a><a class="active" href="/store/<?= e($store['slug']) ?>/cart">Carrito</a></nav></div></header>
<main class="page"><div class="container"><nav class="breadcrumb"><a href="/store/<?= e($store['slug']) ?>">Inicio</a> / Carrito</nav><div class="title"><div><h1>Tu carrito</h1><p><span data-count>0 productos</span> listos para ordenar.</p></div><button class="clear" type="button" data-clear>Vaciar carrito</button></div><div class="layout"><section class="items" data-items></section><aside class="summary"><h2>Resumen del pedido</h2><?php if((float)$store['free_shipping_threshold']>0): ?><div class="shipping-progress" data-shipping-progress><b data-shipping-message></b><div class="shipping-bar"><span data-shipping-bar></span></div></div><?php endif; ?><div class="line"><span>Productos</span><strong data-units>0</strong></div><div class="line"><span>Subtotal</span><strong data-subtotal><?= e($symbol) ?> 0.00</strong></div><div class="line"><span>Entrega</span><strong>Se elige en checkout</strong></div><div class="total"><span>Total</span><span data-total><?= e($symbol) ?> 0.00</span></div><button class="checkout" type="button" data-checkout>Continuar al checkout</button><a class="continue" href="/store/<?= e($store['slug']) ?>#productos">← Continuar comprando</a><div class="notice"><span>🔒</span><span>Los precios y existencias se validan en el servidor antes de crear el pedido.</span></div></aside></div></div></main>
<footer class="footer"><div class="container"><strong><?= e($store['store_name']) ?></strong><span><?= e($store['footer_text'] ?: $store['tagline']) ?></span></div></footer>
<script>
(()=>{const key=<?= json_encode('tmp-store-cart-'.$store['uid']) ?>,symbol=<?= json_encode($symbol) ?>,slug=<?= json_encode($store['slug']) ?>;let cart={};try{cart=JSON.parse(localStorage.getItem(key)||'{}')||{}}catch(e){}const esc=v=>{const d=document.createElement('div');d.textContent=String(v??'');return d.innerHTML},attr=v=>esc(v).replace(/"/g,'&quot;'),money=v=>symbol+' '+Number(v||0).toLocaleString('es-DO',{minimumFractionDigits:2,maximumFractionDigits:2}),entries=()=>Object.values(cart).filter(i=>i&&i.product&&Number(i.quantity)>0);function save(){localStorage.setItem(key,JSON.stringify(cart));render()}function render(){const list=entries(),count=list.reduce((s,i)=>s+Number(i.quantity),0),subtotal=list.reduce((s,i)=>s+(Number(i.product.price)||0)*Number(i.quantity),0),box=document.querySelector('[data-items]');document.querySelector('[data-count]').textContent=count+' producto'+(count===1?'':'s');document.querySelector('[data-units]').textContent=count;document.querySelector('[data-subtotal]').textContent=money(subtotal);document.querySelector('[data-total]').textContent=money(subtotal);document.querySelector('[data-clear]').hidden=!list.length;document.querySelector('[data-checkout]').disabled=!list.length;if(!list.length){box.innerHTML='<div class="empty"><i>🛒</i><h2>Tu carrito está vacío</h2><p>Agrega productos del catálogo para comenzar.</p><a class="button" href="/store/'+encodeURIComponent(slug)+'">Explorar productos</a></div>';return}box.innerHTML=list.map(i=>{const p=i.product,q=Number(i.quantity),url='/store/'+encodeURIComponent(slug)+'/products/'+encodeURIComponent(p.uid);return '<article class="item"><a class="image" href="'+url+'">'+(p.image?'<img src="'+attr(p.image)+'" alt="">':'□')+'</a><div class="info"><small>'+esc(p.category||'Producto')+'</small><h2><a href="'+url+'">'+esc(p.name)+'</a></h2><div class="price">'+(p.price===null?'Consultar':money(p.price))+'</div></div><div class="actions"><div class="qty"><button type="button" data-minus="'+attr(p.uid)+'">−</button><span>'+q+'</span><button type="button" data-plus="'+attr(p.uid)+'">+</button></div><button type="button" class="remove" data-remove="'+attr(p.uid)+'" aria-label="Eliminar">×</button></div></article>'}).join('');box.querySelectorAll('[data-minus]').forEach(b=>b.onclick=()=>{const i=cart[b.dataset.minus];if(!i)return;i.quantity--;if(i.quantity<=0)delete cart[b.dataset.minus];save()});box.querySelectorAll('[data-plus]').forEach(b=>b.onclick=()=>{const i=cart[b.dataset.plus];if(!i)return;i.quantity=Math.min(99,Number(i.quantity)+1);save()});box.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{delete cart[b.dataset.remove];save()})}document.querySelector('[data-clear]').onclick=()=>{if(confirm('¿Vaciar todos los productos del carrito?')){cart={};save()}};document.querySelector('[data-checkout]').onclick=()=>{if(entries().length)location.href='/store/'+encodeURIComponent(slug)+'/checkout'};render()})();
</script>
<?php if((float)$store['free_shipping_threshold']>0): ?><script>
(()=>{const threshold=<?= json_encode((float)$store['free_shipping_threshold']) ?>,key=<?= json_encode('tmp-store-cart-'.$store['uid']) ?>,message=document.querySelector('[data-shipping-message]'),bar=document.querySelector('[data-shipping-bar]');function update(){let cart={};try{cart=JSON.parse(localStorage.getItem(key)||'{}')||{}}catch(e){}const subtotal=Object.values(cart).reduce((sum,item)=>sum+(Number(item?.product?.price)||0)*Number(item?.quantity||0),0),remaining=Math.max(0,threshold-subtotal),progress=Math.max(0,Math.min(100,(subtotal/threshold)*100));message.textContent=remaining<=0?'¡Ya tienes envío gratis!':'Agrega <?= e($symbol) ?> '+remaining.toLocaleString('es-DO',{minimumFractionDigits:2,maximumFractionDigits:2})+' para envío gratis';bar.style.width=progress+'%'}new MutationObserver(update).observe(document.querySelector('[data-subtotal]'),{childList:true,subtree:true,characterData:true});update()})();
</script><?php endif; ?>
</body></html>
